let requestCount = 0;
const hits = new Map(); // client address -> recent request times

function log(level, message) {
  console.log(`${new Date().toISOString()} | ${level} | ${message}`);
}

function send(res, status, body, extraHeaders = {}) {
  const text = typeof body === 'string' ? body : JSON.stringify(body, null, 2);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(text);
}

function errorBody(status, message) {
  return { error: { status, message } };
}

function meta(extra = {}) {
  requestCount += 1;
  return {
    request_id: `req_${String(requestCount).padStart(5, '0')}`,
    served_at: new Date().toISOString(),
    source: 'Neighborhood Tech Hub mock API (synthetic data for i.c.stars Assessment C)',
    ...extra,
  };
}

function isRateLimited(client) {
  const now = Date.now();
  const recent = (hits.get(client) || []).filter((t) => now - t < RATE_LIMIT_WINDOW_MS);
  recent.push(now);
  hits.set(client, recent);
  return recent.length > RATE_LIMIT_MAX;
}

function handle(req, res) {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  const path = url.pathname.replace(/\/+$/, '') || '/';
  const simulate = (url.searchParams.get('simulate') || '').toLowerCase();
  const finish = (status, body, headers) => {
    send(res, status, body, headers);
    log(status >= 400 ? 'WARN' : 'INFO', `${req.method} ${url.pathname}${url.search} -> ${status}`);
  };

  if (req.method !== 'GET') {
    return finish(405, errorBody(405, 'Only GET requests are supported by this mock API.'));
  }
  if (path === '/' || path === '/health') {
    return finish(200, { status: 'ok', endpoints: ['/health', '/api/v1/workshops', '/api/v1/workshops/<id>'] });
  }
  if (!path.startsWith('/api/v1/workshops')) {
    return finish(404, errorBody(404, `No endpoint at ${url.pathname}. Try /api/v1/workshops/<id>.`));
  }
  if (isRateLimited(req.socket.remoteAddress || 'local')) {
    return finish(429, errorBody(429, 'Too many requests. Wait 2 seconds, then try again.'), { 'Retry-After': '2' });
  }
  if (req.headers['x-api-key'] !== API_KEY) {
    return finish(401, errorBody(401, 'Missing or invalid API key. Send it in the x-api-key header.'));
  }

  // Simulated failures for error-handling practice
  if (simulate === '500') return finish(500, errorBody(500, 'Simulated server failure.'));
  if (simulate === '503') return finish(503, errorBody(503, 'Simulated outage. Try again later.'), { 'Retry-After': '2' });
  if (simulate === '429') return finish(429, errorBody(429, 'Simulated rate limit. Wait 2 seconds.'), { 'Retry-After': '2' });
  if (simulate === 'badjson') return finish(200, '{"data": {"id": 1, "title": "Broken resp');

  const respond = () => {
    if (path === '/api/v1/workshops') {
      return finish(200, { data: WORKSHOPS, meta: meta({ count: WORKSHOPS.length }) });
    }
    const match = path.match(/^\/api\/v1\/workshops\/(\d+)$/);
    if (!match) return finish(400, errorBody(400, 'Workshop id must be a whole number, e.g. /api/v1/workshops/7.'));
    const workshop = WORKSHOPS.find((w) => w.id === Number(match[1]));
    if (!workshop) return finish(404, errorBody(404, `No workshop with id ${match[1]}. Valid ids are 1-${WORKSHOPS.length}.`));
    return finish(200, { data: workshop, meta: meta() });
  };
  if (simulate === 'slow') return setTimeout(respond, SLOW_MS);
  return respond();
}

const server = http.createServer(handle);
server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    log('ERROR', `Port ${PORT} is already in use. Is the mock API already running in another terminal?`);
    log('ERROR', `To use another port: node mock-api/server.js 5051  (then set API_BASE_URL=http://localhost:5051 in .env)`);
  } else {
    log('ERROR', err.message);
  }
  process.exit(1);
});
server.listen(PORT, '127.0.0.1', () => {
  log('INFO', `Mock API running at http://localhost:${PORT}  (Ctrl + C to stop)`);
  log('INFO', `Try it: http://localhost:${PORT}/health`);
});
